import{_ as t,o as i,c as a,a2 as n}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Principes de distribution « À Chacun Selon son Travail »","description":"","frontmatter":{},"headers":[],"relativePath":"fr/0006-多劳多得分配原理.md","filePath":"fr/0006-多劳多得分配原理.md"}'),s={name:"fr/0006-多劳多得分配原理.md"};function o(r,e,l,u,d,c){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="principes-de-distribution-«-a-chacun-selon-son-travail-»" tabindex="-1">Principes de distribution « À Chacun Selon son Travail » <a class="header-anchor" href="#principes-de-distribution-«-a-chacun-selon-son-travail-»" aria-label="Permalink to &quot;Principes de distribution « À Chacun Selon son Travail »&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>06</td></tr><tr><td>Module</td><td>Principes généraux et paramètres fondamentaux</td></tr><tr><td>Mots-clés</td><td>À Chacun Selon son Travail, Distribution, Contribution, Contrat Lié à la Production, Équité et efficacité</td></tr></tbody></table><h2 id="i-definition-fondamentale-d-a-chacun-selon-son-travail" tabindex="-1">I. Définition fondamentale d&#39;À Chacun Selon son Travail <a class="header-anchor" href="#i-definition-fondamentale-d-a-chacun-selon-son-travail" aria-label="Permalink to &quot;I. Définition fondamentale d&#39;À Chacun Selon son Travail&quot;">​</a></h2><p>À Chacun Selon son Travail est le principe de distribution central de la Civilisation Symbiotique de l&#39;Ancre : la distribution des valeurs rares telles que les ressources de culture, les opportunités évolutives et les honneurs sociaux repose principalement sur la contribution réelle des individus ou des groupes au réseau symbiotique. Plus la contribution est grande, plus la part obtenue est importante ; plus la contribution est petite, plus la part est petite. À Chacun Selon son Travail s&#39;oppose à la fois à la distribution prédatrice des gains non mérités et à la distribution égalitaire où travailler plus ou moins ne fait aucune différence.</p><p>Le « travail » a une signification spécifique dans la civilisation symbiotique : il ne désigne pas seulement le travail physique, mais toutes les activités ayant des contributions positives au réseau symbiotique, y compris la culture assidue, la création de connaissances, l&#39;innovation technologique, l&#39;entretien des ancres, la gouvernance civilisationnelle et la collaboration raciale. La « récompense » ne désigne pas non plus seulement les ressources matérielles, mais un soutien évolutif complet comprenant les opportunités évolutives, les permissions d&#39;accès aux ancres, les qualifications de mentorat et la priorité dans l&#39;exploration des plans.</p><h2 id="ii-fondements-theoriques-d-a-chacun-selon-son-travail" tabindex="-1">II. Fondements théoriques d&#39;À Chacun Selon son Travail <a class="header-anchor" href="#ii-fondements-theoriques-d-a-chacun-selon-son-travail" aria-label="Permalink to &quot;II. Fondements théoriques d&#39;À Chacun Selon son Travail&quot;">​</a></h2><p>L&#39;établissement du principe À Chacun Selon son Travail repose sur les trois considérations théoriques suivantes :</p><h3 id="_2-1-theorie-de-l-incitation-les-contributions-ont-besoin-de-retour-positif" tabindex="-1">2.1 Théorie de l&#39;incitation : les contributions ont besoin de retour positif <a class="header-anchor" href="#_2-1-theorie-de-l-incitation-les-contributions-ont-besoin-de-retour-positif" aria-label="Permalink to &quot;2.1 Théorie de l&#39;incitation : les contributions ont besoin de retour positif&quot;">​</a></h3><p>L&#39;évolution est un processus exigeant un investissement continu. Si la contribution et la récompense sont découplées, les individus perdent la motivation d&#39;un investissement continu, et l&#39;efficacité évolutive de tout le réseau symbiotique décline. En établissant une boucle de rétroaction positive entre contribution et récompense, À Chacun Selon son Travail motive chaque vie à maximiser son propre potentiel et à créer plus de valeur pour le réseau symbiotique.</p><h3 id="_2-2-theorie-de-l-equite-la-distribution-par-contribution-est-l-equite-la-plus-fondamentale" tabindex="-1">2.2 Théorie de l&#39;équité : la distribution par contribution est l&#39;équité la plus fondamentale <a class="header-anchor" href="#_2-2-theorie-de-l-equite-la-distribution-par-contribution-est-l-equite-la-plus-fondamentale" aria-label="Permalink to &quot;2.2 Théorie de l&#39;équité : la distribution par contribution est l&#39;équité la plus fondamentale&quot;">​</a></h3><p>Dans la civilisation symbiotique, l&#39;équité n&#39;est pas égale à l&#39;égalitarisme. La véritable équité signifie que l&#39;effort de chaque vie reçoit une récompense correspondante. Un cultivateur atteignant un niveau élevé par une culture assidue recevant plus de ressources et d&#39;opportunités est une récompense raisonnable de son effort ; un individu refusant tout effort ne recevant qu&#39;une sécurité de base est aussi une expression de l&#39;équité. À Chacun Selon son Travail protège les droits des travailleurs diligents et des créateurs.</p><h3 id="_2-3-theorie-de-l-efficacite-les-ressources-doivent-circuler-la-ou-elles-creent-le-plus-de-valeur" tabindex="-1">2.3 Théorie de l&#39;efficacité : les ressources doivent circuler là où elles créent le plus de valeur <a class="header-anchor" href="#_2-3-theorie-de-l-efficacite-les-ressources-doivent-circuler-la-ou-elles-creent-le-plus-de-valeur" aria-label="Permalink to &quot;2.3 Théorie de l&#39;efficacité : les ressources doivent circuler là où elles créent le plus de valeur&quot;">​</a></h3><p>Bien que les ressources de culture cosmiques puissent être continuellement augmentées par des moyens techniques, elles restent finies dans un espace-temps donné. Le mécanisme À Chacun Selon son Travail priorise l&#39;allocation des ressources aux individus et groupes à forte contribution et haute efficacité, permettant aux ressources finies de produire un bénéfice évolutif maximal. Ce n&#39;est pas un abandon des faibles, mais une responsabilité envers l&#39;efficacité évolutive globale — ce n&#39;est qu&#39;après l&#39;amélioration de l&#39;efficacité globale que davantage de ressources peuvent être disponibles pour protéger les faibles.</p><h2 id="iii-systeme-d-evaluation-quantitative-des-contributions" tabindex="-1">III. Système d&#39;évaluation quantitative des contributions <a class="header-anchor" href="#iii-systeme-d-evaluation-quantitative-des-contributions" aria-label="Permalink to &quot;III. Système d&#39;évaluation quantitative des contributions&quot;">​</a></h2><p>Pour rendre le principe À Chacun Selon son Travail opérationnel, la civilisation symbiotique a établi un système systématique d&#39;évaluation quantitative des contributions :</p><table tabindex="0"><thead><tr><th>Type de contribution</th><th>Dimension d&#39;évaluation</th><th>Méthode de quantification</th></tr></thead><tbody><tr><td>Contribution de culture</td><td>Vitesse d&#39;élévation du niveau, hauteur du niveau, effet de démonstration des percées</td><td>Le réseau d&#39;ancres enregistre automatiquement les données de culture, converties en valeur de contribution de culture</td></tr><tr><td>Contribution de connaissance</td><td>Partage public des aperçus de culture, création de nouvelles techniques, résultats de recherche théorique</td><td>Évaluée par le comité académique, valorisée par l&#39;influence et l&#39;innovation de la connaissance</td></tr><tr><td>Contribution technologique</td><td>Innovation technologique en ingénierie des lois, optimisation des applications du Fruit Multiplicateur, améliorations du matériel d&#39;ancrage</td><td>Évaluée par le comité technologique, valorisée par l&#39;utilité pratique et la portée de promotion</td></tr><tr><td>Contribution de service</td><td>Heures de mentorat, charge de travail d&#39;entretien des ancres, participation à la gouvernance civilisationnelle</td><td>Le réseau d&#39;ancres enregistre automatiquement la durée et la qualité du service, converties en valeur de contribution de service</td></tr><tr><td>Contribution écologique</td><td>Restauration écologique des planètes, amélioration de la circulation d&#39;énergie des plans, protection environnementale cosmique</td><td>Évaluée par le comité écologique, valorisée par l&#39;ampleur et la durabilité de l&#39;amélioration écologique</td></tr><tr><td>Contribution collaborative</td><td>Participation aux projets de coopération interraciale, contributions aux affaires de la République des Dix Mille Races</td><td>Évaluée par l&#39;Assemblée républicaine, valorisée par la profondeur et les résultats de la collaboration</td></tr></tbody></table><p>La valeur de contribution totale d&#39;un individu est la somme pondérée de tous les types de valeurs de contribution, les pondérations étant ajustées dynamiquement selon les besoins du stade de développement de la civilisation. Les valeurs de contribution sont réglées chaque trimestre, servant de base principale à la distribution des ressources du trimestre suivant.</p><h2 id="iv-le-systeme-de-contrat-lie-a-la-production" tabindex="-1">IV. Le Système de Contrat Lié à la Production <a class="header-anchor" href="#iv-le-systeme-de-contrat-lie-a-la-production" aria-label="Permalink to &quot;IV. Le Système de Contrat Lié à la Production&quot;">​</a></h2><p>Le Contrat Lié à la Production est la conception institutionnelle concrète du principe À Chacun Selon son Travail dans le domaine de la distribution des ressources de culture, dont l&#39;idée centrale est « contracter la production aux groupes, payer selon la production, récompenser la surproduction ».</p><h3 id="_4-1-fonctionnement-de-base" tabindex="-1">4.1 Fonctionnement de base <a class="header-anchor" href="#_4-1-fonctionnement-de-base" aria-label="Permalink to &quot;4.1 Fonctionnement de base&quot;">​</a></h3><ol><li><strong>Contractualisation des ressources</strong> : la civilisation symbiotique confie les ressources de culture d&#39;une certaine région (telles que les veines spirituelles, les champs de médecine, les veines minières d&#39;énergie) à des groupes de cultivateurs ou des communautés raciales</li><li><strong>Quota de production</strong> : fixer un quota de production raisonnable selon la productivité de base de la ressource et la capacité du contractant</li><li><strong>Paiement lié à la production</strong> : la part de ressources obtenue par le contractant est liée à la production réelle ; atteindre le quota donne la part de base, et la surproduction est récompensée proportionnellement</li><li><strong>Exploitation autonome</strong> : à condition de ne pas violer le principe anti-prédation et les réglementations de protection écologique, le contractant a le droit de décider de manière autonome des méthodes de développement et d&#39;utilisation des ressources</li></ol><h3 id="_4-2-avantages-du-contrat-lie-a-la-production" tabindex="-1">4.2 Avantages du Contrat Lié à la Production <a class="header-anchor" href="#_4-2-avantages-du-contrat-lie-a-la-production" aria-label="Permalink to &quot;4.2 Avantages du Contrat Lié à la Production&quot;">​</a></h3><ul><li>Lie directement l&#39;efficacité d&#39;utilisation des ressources collectives aux intérêts personnels du contractant, motivant une culture méticuleuse</li><li>Évite la « tragédie des biens communs » causée par la distribution égale des ressources, améliorant l&#39;efficacité d&#39;utilisation des ressources</li><li>Sous l&#39;incitation des récompenses de surproduction, les contractants sont motivés à innover technologiquement et à optimiser la gestion</li><li>Fournit aux cultivateurs un canal stable d&#39;acquisition de ressources, réduisant la motivation économique du comportement prédateur</li></ul><h3 id="_4-3-protection-contre-les-risques" tabindex="-1">4.3 Protection contre les risques <a class="header-anchor" href="#_4-3-protection-contre-les-risques" aria-label="Permalink to &quot;4.3 Protection contre les risques&quot;">​</a></h3><p>Le Contrat Lié à la Production ne transfère pas entièrement le risque au contractant. La civilisation symbiotique a établi un « Fonds de protection contre les risques contractuels », fournissant une protection de base aux contractants en cas de catastrophes naturelles de force majeure ou de fluctuations de plans, garantissant qu&#39;ils ne perdent pas leurs conditions de culture de base à cause d&#39;accidents.</p><h2 id="v-equilibre-entre-securite-de-base-et-a-chacun-selon-son-travail" tabindex="-1">V. Équilibre entre sécurité de base et À Chacun Selon son Travail <a class="header-anchor" href="#v-equilibre-entre-securite-de-base-et-a-chacun-selon-son-travail" aria-label="Permalink to &quot;V. Équilibre entre sécurité de base et À Chacun Selon son Travail&quot;">​</a></h2><p>À Chacun Selon son Travail ne signifie pas que la civilisation symbiotique est une « société de jungle » complète. Au contraire, À Chacun Selon son Travail doit se combiner avec la sécurité de base d&#39;« Un Chemin pour Chacun » pour réaliser l&#39;unité de l&#39;équité et de l&#39;efficacité.</p><p>La civilisation symbiotique a établi une « Ligne de sécurité évolutive de base », garantissant que chaque vie, quelle que soit sa contribution, puisse obtenir les protections fondamentales suivantes :</p><ul><li>Accès gratuit aux méthodes de base des Trois Cents Systèmes de Culture de l&#39;Origine</li><li>Allocation minimale de ressources de culture (suffisante pour maintenir la culture et la survie de base)</li><li>Services médicaux et éducatifs de base</li><li>Accès au niveau minimal du réseau d&#39;ancres</li></ul><p>Au-dessus de la ligne de sécurité de base, la distribution des ressources suit strictement le principe À Chacun Selon son Travail. Cette structure à deux couches de « sécurité minimale + distribution par contribution » protège à la fois les droits évolutifs fondamentaux des faibles et motive la création et la contribution des forts.</p><h2 id="vi-mecanismes-prevenant-l-alienation-d-a-chacun-selon-son-travail" tabindex="-1">VI. Mécanismes prévenant l&#39;aliénation d&#39;À Chacun Selon son Travail <a class="header-anchor" href="#vi-mecanismes-prevenant-l-alienation-d-a-chacun-selon-son-travail" aria-label="Permalink to &quot;VI. Mécanismes prévenant l&#39;aliénation d&#39;À Chacun Selon son Travail&quot;">​</a></h2><p>À Chacun Selon son Travail peut faire face au risque d&#39;aliénation dans la pratique, et la civilisation symbiotique a établi les mécanismes préventifs suivants :</p><ul><li><strong>Mécanisme anti-monopole</strong> : interdit aux individus ou groupes d&#39;obtenir des contributions excédentaires déraisonnables par le monopole des ressources ; la loi anti-monopole contient des dispositions explicites</li><li><strong>Mécanisme d&#39;équité intergénérationnelle</strong> : les valeurs de contribution ne peuvent pas être entièrement héritées, empêchant la solidification des classes causée par la « contribution héritée »</li><li><strong>Vérification de l&#39;authenticité des contributions</strong> : le réseau d&#39;ancres recoupe les données de contribution, empêchant les fausses déclarations</li><li><strong>Mécanisme d&#39;ajustement dynamique</strong> : les pondérations et normes d&#39;évaluation des contributions sont périodiquement ajustées selon les besoins du développement civilisationnel, empêchant l&#39;expansion excessive d&#39;un seul type de contribution</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>À Chacun Selon son Travail est le principe central du système de distribution de la Civilisation Symbiotique de l&#39;Ancre. Il diffère à la fois du « le fort rafle tout » du prédationisme et de la « marmite commune » de l&#39;égalitarisme ; sur la base de la sécurité fondamentale, il distribue ressources et opportunités selon la contribution, réalisant l&#39;unité de l&#39;équité et de l&#39;efficacité. L&#39;objectif ultime d&#39;À Chacun Selon son Travail est de garantir que l&#39;effort de chaque vie ait une récompense et que le potentiel de chaque vie puisse être pleinement réalisé.</p><h2 id="documents-associes" tabindex="-1">Documents associés <a class="header-anchor" href="#documents-associes" aria-label="Permalink to &quot;Documents associés&quot;">​</a></h2><ul><li>08-人人有路保障体系 (Système de garantie « Un Chemin pour Chacun »)</li><li>22-资源分配联产承包机制 (Système de Contrat Lié à la Production pour la distribution des ressources)</li><li>41-共生劳动法 (Loi du travail symbiotique)</li></ul>',37)])])}const v=t(s,[["render",o]]);export{m as __pageData,v as default};
